from django.shortcuts import get_object_or_404
from django.http import JsonResponse, HttpResponseForbidden
from django.views.decorators.http import require_POST
from django.contrib.auth.decorators import login_required
from .models import BillingInvoice

@login_required
@require_POST
def reopen_archived_invoice(request, invoice_uuid):
    # Enforce that the invoice belongs to the authenticated user's business
    invoice = get_object_or_404(BillingInvoice, uuid=invoice_uuid, business=request.user.business)

    if invoice.status == BillingInvoice.STATUS.archived:
        invoice.status = BillingInvoice.STATUS.active
        invoice.save(update_fields=['status'])
        return JsonResponse({'status': 'reopened', 'uuid': str(invoice.uuid)})

    return JsonResponse({'error': 'Invoice is not in archived state'}, status=400)
